/**
 * lib/metadata.ts
 * ─────────────────────────────────────────────────────────────────
 * Per-page metadata with its own Open Graph and Twitter card.
 * Next.js replaces (does not merge) openGraph from the root layout,
 * so every page builds the full set here.
 * ─────────────────────────────────────────────────────────────────
 */

import type { Metadata } from "next";
import { SITE } from "@/config/site";

// Generated by app/opengraph-image.tsx. Next.js does not inherit it into
// pages that define their own openGraph, so it is set explicitly.
const DEFAULT_IMAGE = "/opengraph-image";

export function pageMetadata({
  title,
  description,
  path,
  image = DEFAULT_IMAGE,
  imageAlt,
}: {
  title: string;
  description: string;
  path: string;
  /** Omit to use the default branch card. */
  image?: string;
  imageAlt?: string;
}): Metadata {
  const fullTitle = `${title} | ${SITE.shortName}`;
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      title: fullTitle,
      description,
      url: path,
      siteName: SITE.shortName,
      locale: "en_UG",
      type: "website",
      images: [{ url: image, alt: imageAlt ?? title }],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      site: "@IEEECavendish",
      images: [image],
    },
  };
}
